{
  "name": "EPICS步进扫描控制组件",
  "name_en": "EPICS Step Scan Control Component",
  "manufacturer": "",
  "description": "用于实验自动化中的非物理软件组件，负责组织EPICS步进扫描流程。它可配置位置器、探测器、触发器、计数器和额外PV，执行逐点扫描、采集数据、处理暂停/中止、发布每点数据并写出扫描文件。",
  "description_en": "A non-physical software component for experiment automation that orchestrates EPICS step-scan workflows. It configures positioners, detectors, triggers, counters, and extra PVs, then executes point-by-point scans, acquires data, handles pause/abort logic, publishes per-point data, and writes scan output files.",
  "actions": [
    {
      "action_name": "auto-add_counter",
      "description": "添加计数器到扫描流程。",
      "description_en": "Add a counter to the scan workflow."
    },
    {
      "action_name": "auto-add_detector",
      "description": "添加探测器到扫描流程。",
      "description_en": "Add a detector to the scan workflow."
    },
    {
      "action_name": "auto-add_extra_pvs",
      "description": "添加需要附带记录的额外PV。",
      "description_en": "Add extra PVs to be recorded with the scan."
    },
    {
      "action_name": "auto-add_positioner",
      "description": "添加扫描位置器。",
      "description_en": "Add a scan positioner."
    },
    {
      "action_name": "auto-add_trigger",
      "description": "添加探测器触发器。",
      "description_en": "Add a detector trigger."
    },
    {
      "action_name": "auto-at_break",
      "description": "设置或清除断点处执行的操作。",
      "description_en": "Set or clear actions to execute at scan breakpoints."
    },
    {
      "action_name": "auto-check_outputs",
      "description": "检查前一步操作输出是否存在错误。",
      "description_en": "Check whether outputs from a previous operation indicate an error."
    },
    {
      "action_name": "auto-clear_data",
      "description": "清空当前扫描数据。",
      "description_en": "Clear current scan data."
    },
    {
      "action_name": "auto-clear_interrupts",
      "description": "清除扫描的中止、暂停和恢复请求。",
      "description_en": "Clear abort, pause, and resume requests for the scan."
    },
    {
      "action_name": "auto-estimate_scan_time",
      "description": "估算扫描总耗时。",
      "description_en": "Estimate the total scan duration."
    },
    {
      "action_name": "auto-init_scandata",
      "description": "初始化扫描数据结构。",
      "description_en": "Initialize scan data structures."
    },
    {
      "action_name": "auto-look_for_interrupts",
      "description": "检查是否有中止、暂停或恢复请求。",
      "description_en": "Check for abort, pause, or resume requests."
    },
    {
      "action_name": "auto-open_output_file",
      "description": "打开扫描输出文件。",
      "description_en": "Open the scan output file."
    },
    {
      "action_name": "auto-post_scan",
      "description": "执行扫描结束后的收尾操作。",
      "description_en": "Run post-scan cleanup operations."
    },
    {
      "action_name": "auto-pre_scan",
      "description": "执行扫描开始前的准备操作。",
      "description_en": "Run pre-scan setup operations."
    },
    {
      "action_name": "auto-prepare_scan",
      "description": "准备步进扫描运行环境。",
      "description_en": "Prepare the step-scan runtime environment."
    },
    {
      "action_name": "auto-publish_data",
      "description": "发布每个扫描点的数据。",
      "description_en": "Publish data for each scan point."
    },
    {
      "action_name": "auto-read_extra_pvs",
      "description": "读取额外PV的当前值。",
      "description_en": "Read current values of extra PVs."
    },
    {
      "action_name": "auto-run",
      "description": "执行完整的步进扫描过程。",
      "description_en": "Execute the full step-scan procedure."
    },
    {
      "action_name": "auto-set_all_scandata",
      "description": "设置全部扫描数据内容。",
      "description_en": "Set all scan data content."
    },
    {
      "action_name": "auto-set_dwelltime",
      "description": "设置每个扫描点的驻留时间。",
      "description_en": "Set the dwell time for each scan point."
    },
    {
      "action_name": "auto-set_error",
      "description": "设置扫描错误信息。",
      "description_en": "Set the scan error message."
    },
    {
      "action_name": "auto-set_info",
      "description": "设置扫描信息属性。",
      "description_en": "Set a scan information attribute."
    },
    {
      "action_name": "auto-verify_scan",
      "description": "校验扫描配置是否有效。",
      "description_en": "Verify that the scan configuration is valid."
    },
    {
      "action_name": "auto-write",
      "description": "写入扫描消息或日志信息。",
      "description_en": "Write a scan message or log entry."
    },
    {
      "action_name": "auto-get_bool",
      "description": "获取布尔状态标志。",
      "description_en": "Get boolean status flag."
    }
  ],
  "tag_hints": [
    "EPICS step scan",
    "scan orchestration",
    "positioner control sequencing",
    "detector triggering",
    "counter acquisition",
    "per-point data publishing",
    "scan file output",
    "pause abort resume handling"
  ]
}

